begin;
-- Requiere las migraciones de reservas, comunas y pausas. No borra reservas.
create table if not exists public.legal_settings(id boolean primary key default true check(id),ready boolean not null default false,version text not null);
insert into public.legal_settings(id,ready,version) values(true,false,'2026-10-28.v1') on conflict do nothing;
create table if not exists public.legal_documents(
 version text not null,kind text not null check(kind in ('terminos','privacidad','cookies','reembolsos')),
 url text not null,content text not null,sha256 text not null check(sha256=encode(sha256(convert_to(content,'UTF8')),'hex')),
 primary key(version,kind));
create table if not exists public.legal_acceptances(
 id uuid primary key default gen_random_uuid(),accepted_at timestamptz not null default clock_timestamp(),
 subject_email text not null,admin_user_id uuid,booking_reference uuid,
 source text not null check(source in ('booking','contact','admin:login','admin:service','admin:slot','admin:edit-booking')),
 version text not null,terms_accepted boolean not null check(terms_accepted),privacy_accepted boolean not null check(privacy_accepted),
 method text not null default 'two_unchecked_required_checkboxes_explicit_submit',
 booking_snapshot jsonb not null default '{}'::jsonb,
 identity_assurance text not null check(identity_assurance in ('declared_email','authenticated_admin')),
 check(length(subject_email)<=254));
alter table public.legal_settings enable row level security;
alter table public.legal_documents enable row level security;
alter table public.legal_acceptances enable row level security;
revoke all on public.legal_settings,public.legal_documents,public.legal_acceptances from public,anon,authenticated;
grant select on public.legal_documents,public.legal_acceptances to authenticated;
drop policy if exists admin_legal_documents on public.legal_documents;
create policy admin_legal_documents on public.legal_documents for select to authenticated using(public.is_admin());
drop policy if exists admin_legal_acceptances on public.legal_acceptances;
create policy admin_legal_acceptances on public.legal_acceptances for select to authenticated using(public.is_admin());
create or replace function public.prevent_legal_mutation() returns trigger language plpgsql set search_path=public as $$
begin raise exception 'Evidencia de aceptación: no se modifica desde la aplicación. Tramita las solicitudes de derechos mediante el procedimiento documentado.';end $$;
drop trigger if exists immutable_legal_acceptances on public.legal_acceptances;
create trigger immutable_legal_acceptances before update or delete on public.legal_acceptances for each row execute function public.prevent_legal_mutation();
drop trigger if exists immutable_legal_documents on public.legal_documents;
create trigger immutable_legal_documents before update or delete on public.legal_documents for each row execute function public.prevent_legal_mutation();
create or replace function public.legal_bundle() returns jsonb language sql stable security definer set search_path=public as $$
 select jsonb_build_object('ready',s.ready,'version',s.version,'documents',(select jsonb_agg(jsonb_build_object('kind',d.kind,'url',d.url,'sha256',d.sha256) order by d.kind) from legal_documents d where d.version=s.version)) from legal_settings s where id
$$;
create or replace function public.record_legal_acceptance(p_email text,p_version text,p_terms boolean,p_privacy boolean,p_source text,p_booking uuid default null,p_admin uuid default null)
returns uuid language plpgsql security definer set search_path=public as $$
declare result uuid;
begin
 if p_terms is distinct from true or p_privacy is distinct from true then raise exception 'Debes aceptar los términos y autorizar la política de privacidad por separado.';end if;
 if not exists(select 1 from legal_settings where id and ready and version=p_version) or (select count(*) from legal_documents where version=p_version)<>4 then raise exception 'Los documentos han cambiado o aún no están habilitados. Recarga y revisa las políticas.';end if;
 if p_email is null or length(p_email)>254 or p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Correo no válido';end if;
 insert into legal_acceptances(subject_email,admin_user_id,booking_reference,source,version,terms_accepted,privacy_accepted,identity_assurance,booking_snapshot)
 values(lower(trim(p_email)),p_admin,p_booking,p_source,p_version,true,true,case when p_admin is null then 'declared_email' else 'authenticated_admin' end,
 coalesce((select jsonb_build_object('service_id',b.service_id,'service_name',v.name,'price_clp',v.price,'starts_at',b.starts_at,'ends_at',b.ends_at,'commune',b.commune) from bookings b join services v on v.id=b.service_id where b.id=p_booking),'{}'::jsonb)) returning id into result;
 return result;
end $$;
-- Se conserva la lógica vigente de duración, comuna, bloqueo y correos; se cierra el acceso anterior sin aceptación.
do $$begin
 if to_regprocedure('public.book_slot_legacy_without_consent(uuid,uuid,text,text,text,timestamp with time zone,text,text)') is null then
  alter function public.book_slot(uuid,uuid,text,text,text,timestamptz,text,text) rename to book_slot_legacy_without_consent;
 end if;
end $$;
revoke all on function public.book_slot_legacy_without_consent(uuid,uuid,text,text,text,timestamptz,text,text) from public,anon,authenticated;
create or replace function public.book_slot(slot_id uuid,service_id uuid,customer_name text,customer_email text,customer_phone text,appointment_start timestamptz,customer_commune text,customer_address text,legal_version text,terms_accepted boolean,privacy_accepted boolean)
returns uuid language plpgsql security definer set search_path=public as $$
declare result uuid;receipt uuid;
begin
 -- Ambos cambios se confirman en una sola transacción, o ninguno.
 result:=book_slot_legacy_without_consent(slot_id,service_id,customer_name,customer_email,customer_phone,appointment_start,customer_commune,customer_address);
 receipt:=record_legal_acceptance(customer_email,legal_version,terms_accepted,privacy_accepted,'booking',result);
 update booking_email_jobs set payload=payload||jsonb_build_object('legal_version',legal_version,'legal_receipt',receipt,'legal_documents',
 (select jsonb_agg(jsonb_build_object('kind',d.kind,'url',d.url,'content',d.content,'sha256',d.sha256) order by d.kind) from legal_documents d where d.version=legal_version))
 where booking_id=result and kind in ('booked','admin_booked');
 return result;
end $$;
create or replace function public.contact_legal_acceptance(p_email text,p_version text,p_terms boolean,p_privacy boolean)
returns uuid language sql security definer set search_path=public as $$select record_legal_acceptance(p_email,p_version,p_terms,p_privacy,'contact')$$;
create or replace function public.admin_legal_acceptance(p_version text,p_terms boolean,p_privacy boolean,p_form text)
returns uuid language plpgsql security definer set search_path=public as $$
declare email text;
begin
 if not public.is_admin() then raise exception 'Acceso denegado';end if;
 if p_form not in ('login','service','slot','edit-booking') or p_form is null then raise exception 'Formulario no válido';end if;
 select u.email into email from auth.users u where u.id=auth.uid();
 return record_legal_acceptance(email,p_version,p_terms,p_privacy,'admin:'||p_form,null,auth.uid());
end $$;
revoke all on function public.prevent_legal_mutation(),public.legal_bundle(),public.record_legal_acceptance(text,text,boolean,boolean,text,uuid,uuid),public.book_slot(uuid,uuid,text,text,text,timestamptz,text,text,text,boolean,boolean),public.contact_legal_acceptance(text,text,boolean,boolean),public.admin_legal_acceptance(text,boolean,boolean,text) from public,anon,authenticated;
grant execute on function public.legal_bundle(),public.book_slot(uuid,uuid,text,text,text,timestamptz,text,text,text,boolean,boolean),public.contact_legal_acceptance(text,text,boolean,boolean) to anon,authenticated;
grant execute on function public.admin_legal_acceptance(text,boolean,boolean,text) to authenticated;

insert into public.legal_documents(version,kind,url,content,sha256) values('2026-10-28.v1','cookies','/legal/2026-10-28/cookies.html',$legal_html$<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Política de cookies y almacenamiento · MB Glowy</title><link rel="stylesheet" href="/legal/legal.css"><meta name="robots" content="noindex"></head><body><header><a href="/">MB Glowy</a><a href="/app/">Reservar</a></header><main><h1>Política de cookies y almacenamiento</h1><p>Versión 2026-10-28.v1 · Chile · 28 de octubre de 2026</p><p class="notice" role="note"><strong>Borrador pendiente de identificar al responsable. No habilitado para nuevas aceptaciones.</strong></p><p><strong>Responsable:</strong> PENDIENTE: nombre legal o razón social del responsable<br><strong>RUT:</strong> PENDIENTE: RUT del negocio, si corresponde<br><strong>Domicilio:</strong> PENDIENTE: domicilio comercial o de contacto<br><strong>Contacto:</strong> <a href="mailto:m.barahona@mbglowy.com">m.barahona@mbglowy.com</a></p><h2>1. Resultado de la revisión técnica</h2><p>El código propio del sitio no instala cookies de publicidad, analítica, seguimiento entre sitios ni píxeles de marketing. No se incorporan gestores publicitarios ni herramientas de medición de terceros. No pedimos una aceptación general de cookies que no utilizamos.</p>
<h2>2. Almacenamiento necesario</h2><table><thead><tr><th>Tecnología</th><th>Finalidad</th><th>Duración</th></tr></thead><tbody><tr><td>sessionStorage: mb-token</td><td>Conservar la sesión de administración en la pestaña. No se usa para visitantes que solo reservan.</td><td>Hasta cerrar la pestaña o sesión; la autorización también depende de la vigencia del token.</td></tr><tr><td>Cache Storage: mb-glowy-v… y service worker</td><td>Archivos estáticos para cargar la PWA: HTML, estilos, scripts, manifiesto y logotipos. El código no almacena respuestas de reservas, datos de clientas, configuración ni sesiones en esa caché.</td><td>Hasta la siguiente actualización que sustituye la versión o hasta que borres los datos del sitio.</td></tr></tbody></table>
<h2>3. Proveedores y conexiones</h2><p>GitHub Pages y Supabase reciben solicitudes de red y pueden registrar información técnica para operar y proteger sus servicios. Zoho recibe los datos de las comunicaciones operativas. El navegador y sistema operativo también gestionan permisos e instalación de la PWA. No se cargan fuentes de Google desde el sitio. No se permite incluir nuevos rastreadores por el solo hecho de aceptar los términos de reserva.</p>
<h2>4. ¿Se requiere un banner?</h2><p>Con la configuración descrita, solo se utiliza almacenamiento técnico necesario y no se solicita consentimiento opcional de rastreo. Las casillas de los formularios cumplen una finalidad distinta: aceptar términos y autorizar el tratamiento de los datos de la solicitud. Si se añaden herramientas no necesarias que traten datos personales, deberá revisarse su base legal y obtener autorización previa cuando corresponda, con opciones claras de rechazo y retirada antes de cargarlas. Esta revisión debe repetirse después de cualquier cambio de integraciones.</p>
<h2>5. Control</h2><p>Puedes borrar los datos y almacenamiento del sitio desde las opciones del navegador. Esto puede cerrar la sesión de administración o impedir funciones sin conexión. No necesitas aceptar cookies opcionales para consultar el catálogo ni ejercer derechos de privacidad.</p><p>Documentos relacionados: <a href="terminos.html">Términos y condiciones</a> · <a href="privacidad.html">Política de privacidad</a> · <a href="cookies.html">Política de cookies y almacenamiento</a> · <a href="reembolsos.html">Política de cancelaciones, retracto y reembolsos</a></p></main><footer><a href="/">Volver al sitio</a></footer></body></html>
$legal_html$,'3e538caea0979edcccda9570bc70dc3216a01d35fcbeba196b63eb7a29939488') on conflict do nothing;

insert into public.legal_documents(version,kind,url,content,sha256) values('2026-10-28.v1','privacidad','/legal/2026-10-28/privacidad.html',$legal_html$<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Política de privacidad · MB Glowy</title><link rel="stylesheet" href="/legal/legal.css"><meta name="robots" content="noindex"></head><body><header><a href="/">MB Glowy</a><a href="/app/">Reservar</a></header><main><h1>Política de privacidad</h1><p>Versión 2026-10-28.v1 · Chile · 28 de octubre de 2026</p><p class="notice" role="note"><strong>Borrador pendiente de identificar al responsable. No habilitado para nuevas aceptaciones.</strong></p><p><strong>Responsable:</strong> PENDIENTE: nombre legal o razón social del responsable<br><strong>RUT:</strong> PENDIENTE: RUT del negocio, si corresponde<br><strong>Domicilio:</strong> PENDIENTE: domicilio comercial o de contacto<br><strong>Contacto:</strong> <a href="mailto:m.barahona@mbglowy.com">m.barahona@mbglowy.com</a></p><h2>1. Responsable y datos tratados</h2><p>El responsable es quien se identifica al inicio de esta política bajo la marca MB Glowy. Para consultas y ejercicio de derechos utiliza el correo allí indicado. En reservas se recaban nombre, correo, teléfono, dirección de atención, comuna, tratamiento, fecha, duración, estado y los datos de aceptación. En contacto se solicitan nombre, correo, servicio de interés y mensaje; antes de abrir tu programa de correo se registra tu correo y aceptación, no el contenido del mensaje. Para administración se tratan el correo de la cuenta, su identificador y sus aceptaciones.</p>
<h2>2. Finalidades y autorización</h2><p>Los datos se utilizan para responder tu solicitud, coordinar y prestar la atención, confirmar o cancelar reservas, enviar recordatorios operativos, proteger el sistema y acreditar qué información aceptaste. La casilla de privacidad autoriza estos usos de manera específica e informada. Puedes no autorizar, en cuyo caso no se enviará el formulario; puedes consultar alternativas de atención a través del correo de contacto.</p><p>No se venden datos ni se usan estas aceptaciones para publicidad. No escribas información de salud, datos de menores, documentos de identidad ni fotografías clínicas en los formularios. Cualquier tratamiento de datos sensibles o atención de menores requiere un procedimiento separado con las autorizaciones legales que correspondan.</p>
<h2>3. Proveedores y destinatarios</h2><p>El sitio se publica en GitHub Pages; Supabase aloja la base de datos, autenticación y funciones; Zoho Mail gestiona los correos. Esos servicios pueden procesar datos técnicos y personales en infraestructura fuera de Chile según la región y configuración contratada. El responsable debe mantener acuerdos de tratamiento, revisar ubicaciones y aplicar las garantías exigibles para transferencias internacionales. El acceso a datos de clientas se limita a personal autorizado y proveedores que intervienen en el servicio, sin perjuicio de requerimientos legales de autoridades competentes.</p>
<h2>4. Plazos y eliminación</h2><p>Se conservarán las reservas mientras sean necesarias para gestionar la atención y resolver solicitudes o responsabilidades legales. Las reservas canceladas o pasadas pueden eliminarse desde administración. Los metadatos de correos enviados se depuran por el proceso programado a los 7 días cuando este se encuentra habilitado; los correos recibidos en los buzones tienen su propio ciclo de conservación.</p><p>El registro separado de aceptación conserva el correo declarado, fecha del servidor, origen, acción, identificador de reserva o cuenta y versiones y textos aceptados. Eliminar una reserva no borra ese registro. Se revisará su necesidad al menos anualmente y se suprimirá o anonimizará cuando deje de existir una finalidad o deber legal que justifique conservarlo. Las solicitudes de supresión se evalúan también respecto de ese registro y de respaldos; no se promete conservación indefinida.</p>
<h2>5. Derechos</h2><p>Puedes solicitar información, acceso, rectificación, eliminación o cancelación, bloqueo y revocar la autorización en los términos de la legislación aplicable, escribiendo al responsable. Verificaremos tu identidad de forma proporcional sin pedir una copia de tu documento por defecto. La revocación no afecta la licitud del tratamiento anterior; algunas obligaciones pueden justificar conservar datos mínimos. Si una solicitud no puede atenderse, se informará el motivo y las vías legales disponibles. No se condiciona el ejercicio de derechos a aceptar nuevas políticas.</p>
<h2>6. Seguridad y trazabilidad</h2><p>Se utilizan HTTPS, cuentas administrativas y controles de acceso en la base de datos. Las aceptaciones no se premarcan. La fecha la genera el servidor y las versiones se conservan con una huella SHA-256. El correo declarado no acredita por sí solo la identidad de una persona; el registro no constituye firma electrónica avanzada ni garantiza la inalterabilidad frente al propietario de la base de datos. No registramos IP ni huella digital del dispositivo como prueba de aceptación.</p>
<h2>7. Cambios normativos</h2><p>Esta política se prepara para Chile. La Ley 19.628 regula actualmente la protección de datos personales. La Ley 21.719 tiene entrada en vigor prevista para el 1 de diciembre de 2026 y exige revisar el procedimiento, las bases de licitud, seguridad, derechos y transferencias antes de esa fecha. La política de cookies explica el almacenamiento técnico del sitio.</p><p>Documentos relacionados: <a href="terminos.html">Términos y condiciones</a> · <a href="privacidad.html">Política de privacidad</a> · <a href="cookies.html">Política de cookies y almacenamiento</a> · <a href="reembolsos.html">Política de cancelaciones, retracto y reembolsos</a></p></main><footer><a href="/">Volver al sitio</a></footer></body></html>
$legal_html$,'6e611490c08f5502401b76095ca7bbfd4ff991d8126b0a517931064921464bde') on conflict do nothing;

insert into public.legal_documents(version,kind,url,content,sha256) values('2026-10-28.v1','reembolsos','/legal/2026-10-28/reembolsos.html',$legal_html$<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Política de cancelaciones, retracto y reembolsos · MB Glowy</title><link rel="stylesheet" href="/legal/legal.css"><meta name="robots" content="noindex"></head><body><header><a href="/">MB Glowy</a><a href="/app/">Reservar</a></header><main><h1>Política de cancelaciones, retracto y reembolsos</h1><p>Versión 2026-10-28.v1 · Chile · 28 de octubre de 2026</p><p class="notice" role="note"><strong>Borrador pendiente de identificar al responsable. No habilitado para nuevas aceptaciones.</strong></p><p><strong>Responsable:</strong> PENDIENTE: nombre legal o razón social del responsable<br><strong>RUT:</strong> PENDIENTE: RUT del negocio, si corresponde<br><strong>Domicilio:</strong> PENDIENTE: domicilio comercial o de contacto<br><strong>Contacto:</strong> <a href="mailto:m.barahona@mbglowy.com">m.barahona@mbglowy.com</a></p><h2>1. Sin cobros en esta web</h2><p>Actualmente MB Glowy no recibe pagos ni anticipos mediante el sitio ni exige un anticipo para reservar. Por ello cancelar una reserva web no genera un reembolso automático: no hay una suma cobrada por esta plataforma que devolver. No se guardan datos bancarios ni de tarjetas.</p>
<h2>2. Cancelación y cambios</h2><p>Para cancelar o solicitar un cambio escribe a reserva@mbglowy.com indicando el código de reserva. Los cambios dependen de disponibilidad. No se aplica una multa automática por cancelar o no asistir. Si no se confirma dentro del plazo comunicado, la hora se libera. Si MB Glowy cancela, se informará y podrás solicitar otra fecha sin obligación de aceptarla.</p>
<h2>3. Derechos legales y retracto</h2><p>Se respetan los derechos irrenunciables de la Ley 19.496. Cuando corresponda un derecho de retracto en una contratación a distancia, se atenderá conforme al artículo 3 bis y sus requisitos, sin hacerte renunciar mediante estas casillas. En servicios, la oportunidad de ejercicio debe evaluarse antes de su prestación conforme al régimen aplicable. Esta política no declara una exclusión general del retracto ni convierte la mera reserva en un cobro.</p>
<h2>4. Pagos por otros medios o servicios ya prestados</h2><p>Si existe un pago ajeno al sitio, una devolución, incumplimiento o prestación defectuosa se evaluará según el acuerdo efectivamente celebrado y las normas de consumo. Escribe indicando servicio, fecha, comprobante y motivo, sin enviar datos completos de tarjeta ni contraseñas. No se retendrán importes automáticamente ni se sustituirá un reembolso legal por un saldo o nueva cita sin tu acuerdo. Se informará por escrito el resultado y, si procede devolución, su importe, medio y plazo aplicable.</p>
<h2>5. Atención de reclamos</h2><p>Puedes presentar una solicitud al responsable identificado en este documento. Esto no limita tu derecho a acudir a SERNAC o a los tribunales competentes. Antes de incorporar cobros o anticipos deberán actualizarse la información previa, los términos, el mecanismo de pago y esta política.</p><p>Documentos relacionados: <a href="terminos.html">Términos y condiciones</a> · <a href="privacidad.html">Política de privacidad</a> · <a href="cookies.html">Política de cookies y almacenamiento</a> · <a href="reembolsos.html">Política de cancelaciones, retracto y reembolsos</a></p></main><footer><a href="/">Volver al sitio</a></footer></body></html>
$legal_html$,'cdad3a9c10c956342068ea705976468604334be3dc324ff23ce1b2b2a73890a2') on conflict do nothing;

insert into public.legal_documents(version,kind,url,content,sha256) values('2026-10-28.v1','terminos','/legal/2026-10-28/terminos.html',$legal_html$<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Términos y condiciones · MB Glowy</title><link rel="stylesheet" href="/legal/legal.css"><meta name="robots" content="noindex"></head><body><header><a href="/">MB Glowy</a><a href="/app/">Reservar</a></header><main><h1>Términos y condiciones</h1><p>Versión 2026-10-28.v1 · Chile · 28 de octubre de 2026</p><p class="notice" role="note"><strong>Borrador pendiente de identificar al responsable. No habilitado para nuevas aceptaciones.</strong></p><p><strong>Responsable:</strong> PENDIENTE: nombre legal o razón social del responsable<br><strong>RUT:</strong> PENDIENTE: RUT del negocio, si corresponde<br><strong>Domicilio:</strong> PENDIENTE: domicilio comercial o de contacto<br><strong>Contacto:</strong> <a href="mailto:m.barahona@mbglowy.com">m.barahona@mbglowy.com</a></p><h2>1. Responsable y alcance</h2><p>MB Glowy presta servicios de estética a domicilio en Chile. Los datos del responsable figuran al inicio de este documento. El sitio permite consultar tratamientos, disponibilidad y solicitar una reserva; no procesa pagos ni cobra anticipos.</p>
<h2>2. Información de los servicios</h2><p>Antes de reservar se muestran el tratamiento, duración, precio en pesos chilenos, comuna, fecha y horas de inicio y término. El precio informado debe incluir los impuestos y cargos obligatorios aplicables. Ningún cargo adicional de traslado puede imponerse después de reservar: cualquier servicio con un costo distinto requiere información y aceptación expresa previa.</p><p>Los servicios estéticos no sustituyen diagnóstico ni tratamiento médico. Antes de la atención se evaluarán la idoneidad del tratamiento y sus contraindicaciones. No envíes antecedentes de salud, fotografías clínicas ni datos sensibles en los formularios de este sitio. Si un procedimiento requiere consentimiento informado específico, deberá obtenerse por separado antes de realizarlo.</p>
<h2>3. Reserva y confirmación</h2><p>La solicitud queda reservada por confirmar y se envía un correo con sus datos y enlace de confirmación. Debes solicitarla con al menos 3 horas de anticipación y confirmar al menos 3 horas antes. Existe un plazo final de gracia hasta 2 horas y 30 minutos antes; pasado ese límite se rechaza la confirmación y se libera el horario. El recordatorio previsto para 5 horas antes se envía solo cuando la reserva existe con esa anticipación. Revisa spam; si no recibes el correo, contacta a reserva@mbglowy.com.</p><p>La disponibilidad respeta la duración completa del tratamiento y la pausa configurada entre citas. En un bloque sin comuna definida, la primera reserva fija Coquimbo, La Serena u Ovalle para el bloque. Si la administración define una comuna, se informa antes de reservar.</p>
<h2>4. Cambios, cancelaciones y reembolsos</h2><p>Puedes solicitar cambios o cancelación a reserva@mbglowy.com indicando tu código de reserva. La nueva fecha depende de disponibilidad. Los cambios efectuados por administración generan una nueva solicitud de confirmación. No se cobra penalidad automática por cancelación o inasistencia en este sitio.</p><p>La <a href="reembolsos.html">política de cancelaciones y reembolsos</a> forma parte de estos términos. No limita los derechos irrenunciables de las personas consumidoras ni presume una renuncia al retracto que proceda conforme a la ley.</p>
<h2>5. Contacto y comunicaciones</h2><p>Solo se utilizan los datos para responder consultas, gestionar la atención y enviar avisos operativos. No se autoriza publicidad mediante estas casillas. Una aceptación de términos no es una suscripción de marketing.</p>
<h2>6. Responsabilidad y derechos</h2><p>MB Glowy debe prestar el servicio con seguridad y diligencia y responder por sus obligaciones legales. Estos términos no excluyen responsabilidad por incumplimiento ni restringen reclamos ante SERNAC o los tribunales competentes. No se exige arbitraje ni un tribunal distinto del permitido por la normativa chilena.</p>
<h2>7. Versiones</h2><p>Una modificación rige para nuevas aceptaciones, no cambia retroactivamente la versión aceptada para una reserva anterior. Se conserva una copia de cada versión en el registro de aceptación.</p><p>Documentos relacionados: <a href="terminos.html">Términos y condiciones</a> · <a href="privacidad.html">Política de privacidad</a> · <a href="cookies.html">Política de cookies y almacenamiento</a> · <a href="reembolsos.html">Política de cancelaciones, retracto y reembolsos</a></p></main><footer><a href="/">Volver al sitio</a></footer></body></html>
